import {HttpClient,HttpHeaders,HttpErrorResponse} from '@angular/common/http'
import { Component, OnInit, Input } from '@angular/core';
import {HomeService} from '../../home.service'
import {NavController} from '@ionic/angular'
import {Router} from '@angular/router'
import { AlertController } from '@ionic/angular';
import { Observable, Subscriber } from 'rxjs';
import num from '../../data/k'
@Component({
  selector: 'app-individual',
  templateUrl: './individual.page.html',
  styleUrls: ['./individual.page.scss'],
})

export class IndividualPage implements OnInit {
  public mf:string;

@Input() k;
private hdrs:any;
selectedFile: File = null;
public inputVal:string;
details=[];
d={};
  constructor(private http:HttpClient,private user:HomeService,private navCtrl:NavController,private router:Router,private alertCtrl:AlertController)
  {
    this.user.individual().subscribe(data =>{
      this.details=data[0] as any;
    })
    this.mf = num;
}
onFileSelected(event){
  this.selectedFile = <File>event.target.files[0];
}
m: Observable<any>;
m1: Observable<any>;
cm:Observable<any>;
pol:Observable<any>;
per:Observable<any>;
aim:Observable<any>;
msg:Observable<any>;
profile($event: Event,d) {
 localStorage.setItem('ind',d);
 const file = ($event.target as HTMLInputElement).files[0];
 if(d=='Profilephoto'){
 this.m = new Observable((subscriber: Subscriber<any>) => {
   this.readFile(file, subscriber);
 });}
else if(d=='About_Mephoto'){
 this.m1 = new Observable((subscriber: Subscriber<any>) => {
   this.readFile(file, subscriber);
 });}
 else if(d=='childhood_and_Educationphoto'){
  this.cm = new Observable((subscriber: Subscriber<any>) => {
    this.readFile(file, subscriber);
  });}
  else if(d=='Political_Careerphoto'){
   this.pol = new Observable((subscriber: Subscriber<any>) => {
     this.readFile(file, subscriber);
   });}
   else if(d=='Personal_Lifephoto'){
    this.per = new Observable((subscriber: Subscriber<any>) => {
      this.readFile(file, subscriber);
    });}
    else if(d=='aims_Goal_and_Dreamphoto'){
     this.aim = new Observable((subscriber: Subscriber<any>) => {
       this.readFile(file, subscriber);
     });}
     else if(d=='Message_For_Followersphoto'){
      this.msg = new Observable((subscriber: Subscriber<any>) => {
        this.readFile(file, subscriber);
      });}

}
readFile(file: File, subscriber: Subscriber<any>) {
 const filereader = new FileReader();
 filereader.readAsDataURL(file);
 filereader.onload = () => {
   subscriber.next(filereader.result);
   var u = localStorage.getItem('n');
   let url = this.mf+u+this.details['id']+"/";

   this.user.individual1(filereader.result,url).subscribe((res:any)=>{
      alert("Refresh to find the changes");
   })
   subscriber.complete();
 };
 filereader.onerror = (error) => {
   subscriber.error(error);
   subscriber.complete();
 };
}


data(c)
{
localStorage.setItem('ind',c);
var u = localStorage.getItem('n');
let url = this.mf+u+this.details['id']+"/";
this.user.individual1(this.details[c],url).subscribe((res:any)=>{
})
alert('saved');
}

ngOnInit() {
}

}
